def soln(n, k, s):
	beg = 0
	end = k - 1
	res = [''] * n
	for i in range(k):
		if not i & 1:
			res[i] = s[beg]
			beg += 1
		else:
			res[i] = s[end]
			end -= 1
	res[:k] = res[k - 1::-1]
	for i in range(k, n):
		res[i] = s[i]
	return ''.join(res)
for _ in range(int(input())):
	(n, k) = map(int, input().split())
	s = input()
	print(soln(n, k, s))
